             <div class="progress-bar-container">
                <div id="user-corruption-bar" class="progress-bar-value"></div>
            </div>
        </div>

        <div class="property">
            <div class="property-name"><span>寿命</span><span id="user-lifespan-value" class="static-value">-- 天</span></div>
        </div>

        <div class="section">
            <div class="section-header" onclick="toggleSection(this)">
                <span>对核心角色的好感度</span>
                <span>▼</span>
            </div>
            <div class="section-content" id="user-affections-container">
            </div>
        </div>
    </div>
</div>

<div class="status-container character-status">
    <div class="status-content-wrapper">
        <div class="tab-buttons" id="character-tab-buttons">
        </div>

        <div id="character-tabs-container">
        </div>
    </div>
</div>

<script>
    const characterList = ["俞红鲤", "俞未央", "苏青禾", "王雨霏", "王南苑", "孟颖", "柳千熏"];
    let activeCharacter = characterList[0];

    function SafeGetValue(obj, path, defaultValue = "N/A") {
        let keys = Array.isArray(path) ? path.slice() : path.split('.');
        let current = obj;
        for (let i = 0; i < keys.length; i++) {
            if (current === undefined || current === null || typeof current !== 'object' || !current.hasOwnProperty(keys[i])) {
                return defaultValue;
            }
            current = current[keys[i]];
        }
        return current ?? defaultValue;
    }

    function updateProgressBar(barId, value, min = 0, max = 100) {
        const progressBar = document.getElementById(barId);
        if (!progressBar) return;

        let numericValue = parseFloat(Array.isArray(value) ? value[0] : value);
        if (isNaN(numericValue)) numericValue = min;

        const clampedValue = Math.max(min, Math.min(max, numericValue));
        const percentage = ((clampedValue - min) / (max - min)) * 100;
        progressBar.style.width = `${percentage}%`;
    }

    function getCorruptionTier(value) {
        const numValue = parseInt(Array.isArray(value) ? value[0] : value, 10);
        if (numValue <= 20) return "【一心一意】";
        if (numValue <= 40) return "【心猿意马】";
        if (numValue <= 70) return "【朝三暮四】";
        if (numValue <= 90) return "【沾花惹草】";
        return "【人尽可妻】";
    }

    function getAffectionTier(value) {
        const numValue = parseInt(Array.isArray(value) ? value[0] : value, 10);
        if (numValue <= 20) return "【陌生】";
        if (numValue <= 30) return "【认识】";
        if (numValue <= 40) return "【熟人】";
        if (numValue <= 50) return "【朋友】";
        if (numValue <= 60) return "【挚友】";
        if (numValue <= 70) return "【恋人未满】";
        if (numValue <= 80) return "【恋人】";
        if (numValue <= 90) return "【挚爱】";
        return "【灵魂伴侣】";
    }

    function toggleSection(element) {
        const content = element.nextElementSibling;
        const arrow = element.querySelector('span:last-child');
        if (!content || !arrow) return;
        content.classList.toggle('expanded');
        arrow.innerText = content.classList.contains('expanded') ? '▲' : '▼';
    }

    function switchTab(characterName) {
        activeCharacter = characterName;
        document.querySelectorAll('.tab-button').forEach(btn => {
            btn.classList.toggle('active', btn.dataset.char === characterName);
        });
        document.querySelectorAll('.character-tab').forEach(tab => {
            tab.classList.toggle('active', tab.id === `tab-${characterName}`);
        });
    }

    async function initDisplay() {
        try {
            const messages = await getChatMessages(getCurrentMessageId());
            const data = messages?.[0]?.data?.stat_data;
            if (!data) {
                console.error("无法加载状态数据");
                return;
            }

            document.getElementById('datetime-common').innerText = `模拟时间： ${SafeGetValue(data, 'world_state.当前时间', ['--'])[0]}`;

            const corruptionValue = SafeGetValue(data, 'user.堕落值', [0]);
            document.getElementById('user-corruption-map').innerText = getCorruptionTier(corruptionValue);
            updateProgressBar('user-corruption-bar', corruptionValue);

            const lifespanValue = SafeGetValue(data, 'user.寿命', ['?'])[0];
            document.getElementById('user-lifespan-value').innerText = `${lifespanValue} 天`;

            const userAffectionsContainer = document.getElementById('user-affections-container');
            userAffectionsContainer.innerHTML = '';
            const fromUserData = SafeGetValue(data, 'user.对各角色好感度', {});
            for (const name of characterList) {
                if (fromUserData[name]) {
                    const value = fromUserData[name];
                    const propHtml = `
                        <div class="property">
                            <div class="property-name"><span>对 ${name} 的好感度</span><i>${getAffectionTier(value)}</i></div>
                            <div class="progress-bar-container">
                                <div id="user-affection-${name}-bar" class="progress-bar-value"></div>
                            </div>
                        </div>`;
                    userAffectionsContainer.insertAdjacentHTML('beforeend', propHtml);
                    setTimeout(() => updateProgressBar(`user-affection-${name}-bar`, value), 10);
                }
            }

            const tabButtonsContainer = document.getElementById('character-tab-buttons');
            const tabsContainer = document.getElementById('character-tabs-container');
            tabButtonsContainer.innerHTML = '';
            tabsContainer.innerHTML = '';

            for (const name of characterList) {
                const buttonHtml = `<button class="tab-button" data-char="${name}" onclick="switchTab('${name}')">${name}</button>`;
                tabButtonsContainer.insertAdjacentHTML('beforeend', buttonHtml);

                const charAffectionValue = SafeGetValue(data, `characters.${name}.对user的好感度`, [0]);

                const tabHtml = `
                    <div class="character-tab" id="tab-${name}">
                        <h3><i>${name}</i></h3>
                        <div class="property">
                            <div class="property-name"><span>对 {{user}} 的好感度</span><i>${getAffectionTier(charAffectionValue)}</i></div>
                            <div class="progress-bar-container">
                                <div id="char-affection-${name}-bar" class="progress-bar-value"></div>
                            </div>
                        </div>
                        <div class="property">
                            <div class="property-name">系统积分</div>
                            <div class="static-value">${SafeGetValue(data, 'system.积分', [0])[0]}</div>
                        </div>
                        <div class="property">
                            <div class="property-name">系统存储积分</div>
                            <div class="static-value">${SafeGetValue(data, 'system.存储积分', [0])[0]}</div>
                        </div>
                    </div>`;
                tabsContainer.insertAdjacentHTML('beforeend', tabHtml);
                updateProgressBar(`char-affection-${name}-bar`, charAffectionValue);
            }
            switchTab(activeCharacter);

        } catch (error) {
            console.error('状态栏加载出错:', error);
            document.body.innerHTML = `<p style='color:red; padding:10px;'>状态栏加载出错: ${error.message}</p>`;
        }
    }

    document.addEventListener('DOMContentLoaded', initDisplay);

</script>
</body>
</html>
